def fibonacci(n):
    if n <= 0:
        print("Incorrect input")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        fib_sequence = [0, 1]
        while len(fib_sequence) < n:
            next_value = sum(fib_sequence[-2:])
            fib_sequence.append(next_value)
        return fib_sequence[n-1]

print(fibonacci(50))
